"""Widget foundations.

Every widget — layout, display, or interactive — derives from
:class:`BaseWidget`.  The class hierarchy mirrors the documentation
categories (see ``docs/widgets.md``):

- ``widgets.layout``      — widgets that arrange children (Column, Row,
  Center, ListView)
- ``widgets.display``     — widgets that present content (Text)
- ``widgets.interactive`` — widgets the user acts on (Button, Link)
"""

from __future__ import annotations

from typing import Any

from workpeg.ui.actions import Action
from workpeg.ui.state import Binding, State


WidgetChild = "BaseWidget | str | int | float | Binding | None"


def serialize_value(value: Any, state: State | None = None) -> Any:
    if isinstance(value, BaseWidget):
        return value.to_schema(state=state)

    if isinstance(value, Binding):
        return value.to_schema()

    if isinstance(value, Action):
        return value.to_schema()

    if isinstance(value, list | tuple):
        return [serialize_value(item, state=state) for item in value]

    if isinstance(value, dict):
        return {
            key: serialize_value(item, state=state)
            for key, item in value.items()
        }

    return value


class BaseWidget:
    widget_type = "BaseWidget"

    def __init__(
        self,
        *,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        self.key = key
        self.visible = visible
        self.disabled = disabled
        self.metadata = metadata or {}

    def props(self) -> dict[str, Any]:
        return {}

    def children(self) -> list[WidgetChild]:
        return []

    def to_schema(self, state: State | None = None) -> dict[str, Any]:
        return {
            "type": self.widget_type,
            "props": {
                "key": self.key,
                "visible": serialize_value(self.visible, state=state),
                "disabled": serialize_value(self.disabled, state=state),
                "metadata": self.metadata,
                **serialize_value(self.props(), state=state),
            },
            "children": [
                serialize_value(child, state=state)
                for child in self.children()
                if child is not None
            ],
        }
